import{_ as r,r as n,o as a,c,e as i,a as s,s as p}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Application - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Application container","slug":"application-container","link":"#application-container","children":[{"level":4,"title":"Binding a type into the container","slug":"binding-a-type-into-the-container","link":"#binding-a-type-into-the-container","children":[]},{"level":4,"title":"Resolving a type from the container","slug":"resolving-a-type-from-the-container","link":"#resolving-a-type-from-the-container","children":[]},{"level":4,"title":"Binding a \\"shared\\" type into the container","slug":"binding-a-shared-type-into-the-container","link":"#binding-a-shared-type-into-the-container","children":[]},{"level":4,"title":"Binding an existing instance into the container","slug":"binding-an-existing-instance-into-the-container","link":"#binding-an-existing-instance-into-the-container","children":[]},{"level":4,"title":"Binding an interface to an implementation","slug":"binding-an-interface-to-an-implementation","link":"#binding-an-interface-to-an-implementation","children":[]},{"level":3,"title":"Where to register bindings","slug":"where-to-register-bindings","link":"#where-to-register-bindings","children":[]}]},{"level":2,"title":"Service providers","slug":"service-providers","link":"#service-providers","children":[{"level":4,"title":"Defining a service provider","slug":"defining-a-service-provider","link":"#defining-a-service-provider","children":[]},{"level":4,"title":"Registering a service provider at run-time","slug":"registering-a-service-provider-at-run-time","link":"#registering-a-service-provider-at-run-time","children":[]}]},{"level":2,"title":"Application events","slug":"application-events","link":"#application-events","children":[{"level":4,"title":"Request events","slug":"request-events","link":"#request-events","children":[]},{"level":4,"title":"Container events","slug":"container-events","link":"#container-events","children":[]}]},{"level":2,"title":"Application helpers","slug":"application-helpers","link":"#application-helpers","children":[{"level":4,"title":"Finding the application environment","slug":"finding-the-application-environment","link":"#finding-the-application-environment","children":[]},{"level":4,"title":"Determine the execution context","slug":"determine-the-execution-context","link":"#determine-the-execution-context","children":[]}]}],"relativePath":"1.x/services/application.md","filePath":"1.x/services/application.md"}'),d={name:"1.x/services/application.md"};function l(h,e,g,u,v,m){const t=n("pre-heading"),o=n("post-heading");return a(),c("div",null,[i(t),e[0]||(e[0]=s("h1",null,"Application",-1)),i(o),e[1]||(e[1]=p(`<h2 id="application-container"><a href="#application-container" class="header-anchor">#</a> Application container</h2><p>The inversion of control (IoC) container is a tool for managing class dependencies. Dependency injection is a method of removing hard-coded class dependencies. Instead, the dependencies are injected at run-time, allowing for greater flexibility as dependency implementations may be swapped easily.</p><h4 id="binding-a-type-into-the-container"><a href="#binding-a-type-into-the-container" class="header-anchor">#</a> Binding a type into the container</h4><p>There are two ways the IoC container can resolve dependencies: via Closure callbacks or automatic resolution. First, we&#39;ll explore Closure callbacks. First, a &quot;type&quot; may be bound into the container:</p><pre><code>App::bind(&#39;foo&#39;, function($app) {
    return new FooBar;
});
</code></pre><h4 id="resolving-a-type-from-the-container"><a href="#resolving-a-type-from-the-container" class="header-anchor">#</a> Resolving a type from the container</h4><pre><code>$value = App::make(&#39;foo&#39;);
</code></pre><p>When the <code>App::make</code> method is called, the Closure callback is executed and the result is returned.</p><h4 id="binding-a-shared-type-into-the-container"><a href="#binding-a-shared-type-into-the-container" class="header-anchor">#</a> Binding a &quot;shared&quot; type into the container</h4><p>Sometimes you may wish to bind something into the container that should only be resolved once, and the same instance should be returned on subsequent calls into the container:</p><pre><code>App::singleton(&#39;foo&#39;, function() {
    return new FooBar;
});
</code></pre><h4 id="binding-an-existing-instance-into-the-container"><a href="#binding-an-existing-instance-into-the-container" class="header-anchor">#</a> Binding an existing instance into the container</h4><p>You may also bind an existing object instance into the container using the <code>instance</code> method:</p><pre><code>$foo = new Foo;

App::instance(&#39;foo&#39;, $foo);
</code></pre><h4 id="binding-an-interface-to-an-implementation"><a href="#binding-an-interface-to-an-implementation" class="header-anchor">#</a> Binding an interface to an implementation</h4><p>In some cases, a class may depend on an interface implementation, not a &quot;concrete type&quot;. When this is the case, the <code>App::bind</code> method must be used to inform the container which interface implementation to inject:</p><pre><code>App::bind(&#39;UserRepositoryInterface&#39;, &#39;DbUserRepository&#39;);
</code></pre><p>Now consider the following code:</p><pre><code>$users = App::make(&#39;UserRepositoryInterface&#39;);
</code></pre><p>Since we have bound the <code>UserRepositoryInterface</code> to a concrete type, the <code>DbUserRepository</code> will automatically be injected into this controller when it is created.</p><h3 id="where-to-register-bindings"><a href="#where-to-register-bindings" class="header-anchor">#</a> Where to register bindings</h3><p>IoC bindings, like <a href="./events.html">event handlers</a>, generally fall under the category of &quot;bootstrap code&quot;. In other words, they prepare your application to actually handle requests, and usually need to be executed before a route or controller is actually called. The most common place is the <code>boot</code> method of a <a href="./../plugin/registration.html#registration-methods">Plugin registration file</a>. Alternatively, plugins can supply a file named <strong>init.php</strong> in the plugin directory that you can use to place IoC registration logic.</p><h2 id="service-providers"><a href="#service-providers" class="header-anchor">#</a> Service providers</h2><p>Service providers are a great way to create libraries and perform group related IoC registrations in a single location. Within a service provider, you might register a custom authentication driver, register your application&#39;s repository classes with the IoC container, or even setup a custom Artisan command.</p><p>In fact, <a href="./../plugin/registration.html">plugin registration files</a> inherit service providers and most of the core components include service providers. All of the registered service providers for your application are listed in the <code>providers</code> array of the <code>config/app.php</code> configuration file.</p><h4 id="defining-a-service-provider"><a href="#defining-a-service-provider" class="header-anchor">#</a> Defining a service provider</h4><p>To create a service provider, simply extend the <code>October\\Rain\\Support\\ServiceProvider</code> class and define a <code>register</code> method:</p><pre><code>use October\\Rain\\Support\\ServiceProvider;

class FooServiceProvider extends ServiceProvider
{

    public function register()
    {
        $this-&gt;app-&gt;bind(&#39;foo&#39;, function() {
            return new Foo;
        });
    }

}
</code></pre><p>Note that in the <code>register</code> method, the application IoC container is available to you via the <code>$this-&gt;app</code> property. Once you have created a provider and are ready to register it with your application, simply add it to the <code>providers</code> array in your <code>app</code> configuration file.</p><h4 id="registering-a-service-provider-at-run-time"><a href="#registering-a-service-provider-at-run-time" class="header-anchor">#</a> Registering a service provider at run-time</h4><p>You may also register a service provider at run-time using the <code>App::register</code> method:</p><pre><code>App::register(&#39;FooServiceProvider&#39;);
</code></pre><h2 id="application-events"><a href="#application-events" class="header-anchor">#</a> Application events</h2><h4 id="request-events"><a href="#request-events" class="header-anchor">#</a> Request events</h4><p>You can register special events before a requested is routed using the <code>before</code> and <code>after</code> methods:</p><pre><code>App::before(function ($request) {
    // Code to execute before the request is routed
});

App::after(function ($request) {
    // Code to execute after the request is routed
});
</code></pre><h4 id="container-events"><a href="#container-events" class="header-anchor">#</a> Container events</h4><p>The service container fires an event each time it resolves an object. You may listen to this event using the <code>resolving</code> method:</p><pre><code>App::resolving(function ($object, $app) {
    // Called when container resolves object of any type...
});

App::resolving(&#39;foo&#39;, function ($fooBar, $app) {
    // Called when container resolves objects using hint &quot;foo&quot;...
});

App::resolving(&#39;Acme\\Blog\\Classes\\FooBar&#39;, function ($fooBar, $app) {
    // Called when container resolves objects of type &quot;FooBar&quot;...
});
</code></pre><p>As you can see, the object being resolved will be passed to the callback, allowing you to set any additional properties on the object before it is given to its consumer.</p><h2 id="application-helpers"><a href="#application-helpers" class="header-anchor">#</a> Application helpers</h2><h4 id="finding-the-application-environment"><a href="#finding-the-application-environment" class="header-anchor">#</a> Finding the application environment</h4><p>You may use the <code>environment</code> method to discover the application environment as determined by the <a href="./../setup/configuration.html#environment-configuration">environment configuration</a>.</p><pre><code>// production
App::environment();
</code></pre><h4 id="determine-the-execution-context"><a href="#determine-the-execution-context" class="header-anchor">#</a> Determine the execution context</h4><p>It is possible to know if the current request is being performed in the administrative back-end area using the <code>runningInBackend</code> method.</p><pre><code>App::runningInBackend();
</code></pre><p>You may also use the <code>runningInConsole</code> method to check if the executing code is taking place inside the <a href="./../console/commands.html">command line interface</a>:</p><pre><code>App::runningInConsole();
</code></pre>`,49))])}const b=r(d,[["render",l]]);export{y as __pageData,b as default};
